<script>
function notesActionStudio(){return {thoughts:'',sourceUrl:'',purpose:'general',projectId:'',file:null,quote:null,busy:false,message:'',calendarTask:null,calendarTitle:'',init(){this.$watch('calendarTask',v=>{if(v!==null)this.$nextTick(()=>this.$refs.calendarTitle?.focus())})},async call(url,data){const res=await fetch(url,{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,'Accept':'application/json'},body:data});const json=await res.json();if(!res.ok)throw new Error(Object.values(json.errors||{}).flat().join(' ')||json.message||'Request failed.');return json},async estimate(){this.busy=true;this.message='';this.quote=null;try{const data=new FormData();data.append('thoughts',this.thoughts);data.append('source_url',this.sourceUrl);data.append('purpose',this.purpose);data.append('project_id',this.projectId);if(this.file)data.append('file',this.file);this.quote=await this.call(@js(route('user.ai.mind.estimate')),data)}catch(e){this.message=e.message}finally{this.busy=false}},async generate(){if(!this.quote)return;this.busy=true;this.message='';try{const data=new FormData();data.append('token',this.quote.token);const out=await this.call(@js(route('user.ai.mind.think')),data);window.location.assign(out.url)}catch(e){this.message=e.message;this.quote=null}finally{this.busy=false}}}}
</script>
